<?php require_once __DIR__.'/ui.php';use Srms\Reports;use Srms\Auth;page_heading($title,'Filter records and export the matching results.');$contact=$type==='property_contacts';$exportFilters=['type'=>$type,'from'=>$_GET['from']??'','to'=>$_GET['to']??'','locality'=>$_GET['locality']??'','q'=>$_GET['q']??'','status'=>$_GET['status']??'','method'=>$_GET['method']??'','year'=>$_GET['year']??'','account_number'=>$_GET['account_number']??''];?><section class="panel"><form method="get" class="toolbar wrap"><input type="hidden" name="r" value="reports"><?php $types=Reports::TYPES;if(Auth::owner())$types=array_intersect_key($types,array_flip(['balances','billing','collections','arrears','credits']));foreach(['status','method','year','account_number'] as $carry)if(isset($_GET[$carry]))hidden($carry,$_GET[$carry]);field('type','Report',$type,'select',true,$types);if(!$contact){field('from','From date',$_GET['from']??'','date');field('to','To date',$_GET['to']??'','date');}else field('q','Account number or owner',$_GET['q']??'');field('locality','Locality',$_GET['locality']??'');?><button class="button primary">Apply filters</button></form><div class="panel-heading"><h2><?=e(Reports::TYPES[$type])?></h2><div class="actions"><?php foreach($contact?['csv'=>'CSV','xlsx'=>'Excel']:['pdf'=>'PDF','xlsx'=>'Excel','csv'=>'CSV'] as $format=>$label):?><a class="button small" href="<?=e(url('export',$exportFilters+['format'=>$format]))?>">Download <?=e($label)?></a><?php endforeach?></div></div><?php if($contact):?><p>One row per current owner. Jointly owned properties have multiple rows; properties without owners are also included. Phone numbers are separated by semicolons. Assessment years and ground rent list approved assessments only. Arrears are unpaid bills from years before <?=e(date('Y'))?>. Balances include penalties and adjustments. Property totals repeat for joint owners; do not sum duplicate Account numbers. All <?=count($rows)?> matching rows are included in exports.</p><p>Previewing the first <?=min(100,count($rows))?> rows.</p><?php data_table(array_slice($rows,0,100),['account_number'=>'Account number','locality'=>'Locality','owner_name'=>'Owner','organization'=>'Organization','owner_phones'=>'Phones','owner_email'=>'Email','years_assessed'=>'Years assessed','ground_rent_by_year_ghs'=>'Ground rent by year (GHS)','arrears_ghs'=>'Arrears (GHS)','plot_size'=>'Plot size','plot_size_unit'=>'Unit','address_line'=>'Address line','ownership_share_percent'=>'Share (%)']);else:data_table($rows);endif?></section>